    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: In a twin pregnancy, "Twin-to-Twin Transfusion Syndrome" (TTTS) most commonly presents in which trimester?', '["First", "Second (usually 16-24 weeks)", "Third", "Postpartum"]', 1, 'Early second trimester is the peak time for development and treatment. (ACOG)'),
    (v_topic_id, '202: What is the primary ultrasound finding used to diagnose TTTS?', '["Size discordance", "Fluid discordance (Oligohydramnios in donor, Polyhydramnios in recipient)", "Fused placentas", "Amniotic band"]', 1, 'Defined as MVP < 2cm in one sac and > 8cm in the other. (Gabbe)'),
    (v_topic_id, '203: "Acardiac Twinning" (TRAP sequence) involves a pump twin and a twin with no:', '["Legs", "Heart", "Head", "Skin"]', 1, 'The pump twin provides blood to the acardiac twin via retrograde flow. (Williams)'),
    (v_topic_id, '204: What is the most common cause of death for the "Pump Twin" in a TRAP sequence?', '["Anemia", "High-output heart failure and hydrops", "Infection", "Placental abruption"]', 1, 'The pump twin''s heart has to work for two. (Gabbe)'),
    (v_topic_id, '205: At what gestational age is delivery typically recommended for "uncomplicated" Monochorionic/Diamniotic twins?', '["32-34 weeks", "34-37 weeks (usually 36w0d to 36w6d)", "39-40 weeks", "Induction at 41 weeks"]', 1, 'Earlier than dichorionic twins due to the risk of sudden late demise. (ACOG)'),
    (v_topic_id, '206: "Monoamniotic-monochorionic" (MoMo) twins are typically delivered at 32-34 weeks via:', '["Vaginal delivery", "Cesarean section", "Vacuum extraction", "Induction"]', 1, 'C-section is mandatory to avoid cord entanglement during labor. (ACOG)'),
    (v_topic_id, '207: "Vanishing Twin" refers to:', '["The birth of one twin", "The early loss/resorption of one embryo in a multifetal gestation", "A twin that is born very small", "None of the above"]', 1, 'Often occurs in the first trimester. (Beckmann)'),
    (v_topic_id, '208: "Fetal Growth Restriction" (FGR) in a fetus with "Absent" end-diastolic flow in the umbilical artery should be managed by:', '["Repeat Doppler in 1 week", "Delivery (if > 32-34 weeks) or intensive daily monitoring", "Immediate C-section regardless of age", "Aspirin"]', 1, 'Indicates significant placental resistance. (ACOG)'),
    (v_topic_id, '209: If "Reversed" end-diastolic flow (REDF) is seen at 30 weeks, what is the next step?', '["Steroids and delivery within 24-48 hours", "Recheck in 1 week", "Home monitoring", "Iron supplements"]', 0, 'REDF is an ominous sign; the risk of stillbirth is very high. (Williams)'),
    (v_topic_id, '210: What is the "Ductus Venosus" Doppler used for in FGR?', '["To screen for Down syndrome", "To assess late-stage fetal heart failure (shunting blood to the heart)", "To measure fetal weight", "To check the placenta"]', 1, 'Abnormal a-wave in the Ductus Venosus is a very late sign of compromise. (Gabbe)'),
    (v_topic_id, '211: "Chronic Hypertension" is associated with a 3-4 fold increased risk of:', '["Gestational diabetes", "Placental abruption", "Congenital heart disease", "Post-term pregnancy"]', 1, 'Due to vascular damage in the decidua. (ACOG)'),
    (v_topic_id, '212: A woman with "Chronic Hypertension" develops new-onset proteinuria at 30 weeks. Diagnosis?', '["Gestational hypertension", "Superimposed pre-eclampsia", "Renal failure", "Normal pregnancy"]', 1, 'Must distinguish from stable proteinuria if present at baseline. (Williams)'),
    (v_topic_id, '213: "Labetalol" should be avoided in pregnant women with:', '["Diabetes", "Asthma or Bradycardia", "Anemia", "Obesity"]', 1, 'It is a non-selective beta-blocker. (Beckmann)'),
    (v_topic_id, '214: "Hydralazine" for acute hypertension in pregnancy works by:', '["Direct vasodilation of arterioles", "Beta-blockade", "Alpha-blockade", "Diuresis"]', 0, 'Used IV for hypertensive emergencies. (Gabbe)'),
    (v_topic_id, '215: What is the "target" blood pressure during the treatment of a hypertensive emergency in pregnancy?', '["120/80", "140-150 / 90-100", "90/60", "100/70"]', 1, 'Avoid dropping the BP too rapidly to prevent placental hypoperfusion. (ACOG)'),
    (v_topic_id, '216: Which of the following "Anti-hypertensives" are generally avoided in the 1st trimester due to potential (though small) risks of malformations?', '["Methyldopa", "Labetalol", "ACE inhibitors (Lisinopril)", "Calcium channel blockers"]', 2, 'ACE inhibitors/ARBs are strictly contraindicated in the 2nd and 3rd trimesters due to fetal renal failure. (ACOG)'),
    (v_topic_id, '217: "Magnesium Sulfate" used for 48 hours for neuroprotection in a 28-week delivery helps reduce the risk of:', '["Respiratory distress", "Cerebral Palsy", "Sepsis", "Blindness"]', 1, 'Standard of care for imminent preterm birth < 32 weeks. (ACOG)'),
    (v_topic_id, '218: A woman at 31 weeks has "PPROM" and is being managed expectantly. She develops "Chorioamnionitis." Management?', '["Give tocolytics to delay delivery", "Immediate delivery (regardless of gestational age)", "Antibiotics only and wait until 34 weeks", "Bed rest"]', 1, 'Infection is an indication for delivery. (Williams)'),
    (v_topic_id, '219: What is the most common maternal complication of "HELLP Syndrome"?', '["DIC", "Liver rupture", "Placental abruption", "Acute Kidney Injury"]', 0, 'Occurs in ~20% of HELLP cases. (Gabbe)'),
    (v_topic_id, '220: "Subcapsular Liver Hematoma" in HELLP presents with:', '["Painless jaundice", "Sudden-onset severe RUQ pain, shoulder pain, and hypotension", "Fever", "Itching"]', 1, 'May require emergent surgery or embolization. (Williams)'),
    (v_topic_id, '221: A "Biophysical Profile" (BPP) of 0/10 or 2/10 indicates:', '["Reassurance", "Repeat in 24 hours", "Immediate delivery", "Normal for a sleeping fetus"]', 2, 'Highly suggestive of significant fetal hypoxia/acidosis. (ACOG)'),
    (v_topic_id, '222: "Amniotic Fluid Volume" (AFV) in the BPP reflects fetal ____ over time.', '["Growth", "Renal perfusion and oxygenation", "Breathing", "Tone"]', 1, 'It is the marker of chronic well-being. (Beckmann)'),
    (v_topic_id, '223: After a "Minor Trauma" (e.g., car accident or fall), how long should a viable pregnant woman be monitored?', '["1 hour", "4-6 hours (with CTG monitoring)", "24 hours", "No monitoring needed"]', 1, 'If no contractions, bleeding, or FHR issues, she can be discharged. (ACOG)'),
    (v_topic_id, '224: "Abruptio Placentae" after trauma is most likely to occur within what time frame?', '["1 week", "First 2-6 hours", "Immediately only", "Third trimester only"]', 1, 'Most occur within a few hours of the event. (Williams)'),
    (v_topic_id, '225: The "Kleihauer-Betke" test is routinely used after trauma to:', '["Check for fetal broken bones", "Detect fetomaternal hemorrhage (FMH) and guide RhoGAM dosing", "Diagnose infection", "Measure hCG"]', 1, 'Even minor trauma can cause FMH. (ACOG)'),
    (v_topic_id, '226: "Uterine Rupture" is a medical emergency. What is the most common cause?', '["Breech baby", "Dehiscence of a previous Cesarean scar during labor", "Multiple gestation", "Trauma"]', 1, 'Risk is highest with classical or T-shaped scars. (Beckmann)'),
    (v_topic_id, '227: A woman in labor suddenly has "painless" loss of fetal station and maternal shock. Diagnosis?', '["Placenta previa", "Uterine rupture", "Abruption", "Cord prolapse"]', 1, 'Pain may be masked by an epidural. (Williams)'),
    (v_topic_id, '228: "Acute Fatty Liver of Pregnancy" (AFLP) usually occurs in the:', '["First trimester", "Second trimester", "Third trimester", "Postpartum only"]', 2, 'Requires immediate delivery and intensive care. (ACOG)'),
    (v_topic_id, '229: What laboratory finding is typical for AFLP but NOT for HELLP?', '["Elevated LFTs", "Low platelets", "Severe hypoglycemia and prolonged ammonia levels", "Hemolysis"]', 2, 'Liver failure signs are prominent in AFLP. (Gabbe)'),
    (v_topic_id, '230: "Intrahepatic Cholestasis of Pregnancy" (ICP) increases the risk of "Stillbirth." What is the suspected mechanism?', '["Maternal hypertension", "Bile acid-induced fetal cardiac arrhythmia or placental vasospasm", "Infection", "Diabetes"]', 1, 'The risk increases as bile acid levels rise (> 40 or > 100). (ACOG)'),
    (v_topic_id, '231: "Ursodeoxycholic acid" (Ursodiol) for ICP primarily:', '["Prevents stillbirth", "Reduces maternal pruritus and bile acid levels", "Increases fetal weight", "Stops labor"]', 1, 'While it improves symptoms, its ability to prevent stillbirth is still debated. (ACOG)'),
    (v_topic_id, '232: "Septic Pelvic Thrombophlebitis" (SPT) is most common after which mode of delivery?', '["Vaginal delivery", "Cesarean section (especially for chorioamnionitis)", "Vacuum delivery", "Forceps delivery"]', 1, 'Usually presents with a "picket-fence" fever pattern. (Williams)'),
    (v_topic_id, '233: What is the classic response of SPT to heparin?', '["No change", "Resolution of fever within 24-48 hours", "Bleeding", "Pain"]', 1, 'Sometimes used as a diagnostic tool. (Gabbe)'),
    (v_topic_id, '234: "Endometritis" is most commonly caused by which type of bacteria?', '["Single organism (e.g., E. coli)", "Polymicrobial (anerobes and aerobes from the vagina)", "Staph aureus", "Viruses"]', 1, 'Treatment must be broad-spectrum (e.g., Clinda/Gent). (ACOG)'),
    (v_topic_id, '235: A breastfeeding woman with "Mastitis" develops a fluctuant, painful mass. Management?', '["Oral antibiotics only", "Incision and Drainage or Needle Aspiration, and CONTINUE antibiotics", "Stop breastfeeding", "C-section"]', 1, 'Indicates a breast abscess. (Beckmann)'),
    (v_topic_id, '236: "Postpartum Thyroiditis" (Phase 1) is usually:', '["Hyperthyroid", "Hypothyroid", "Euthyroid", "Goiter only"]', 0, 'Followed by a hypothyroid phase and then usually recovery. (ACOG)'),
    (v_topic_id, '237: A "Complete" Hydatidiform Mole results from the fertilization of an "empty" egg by:', '["Two sperm", "One sperm that duplicates its chromosomes (46,XX)", "One egg", "None of the above"]', 1, 'All genetic material is paternal. (Williams)'),
    (v_topic_id, '238: A "Partial" Hydatidiform Mole results from the fertilization of a normal egg by:', '["One sperm", "Two sperm (resulting in triploidy, 69,XXX or 69,XXY)", "Three sperm", "Zero sperm"]', 1, 'A non-viable fetus or fetal parts may be present. (Gabbe)'),
    (v_topic_id, '239: Which type of mole has a HIGHER risk of malignant transformation (GTN)?', '["Complete mole", "Partial mole", "They are equal", "Neither"]', 0, 'Complete mole has a 15-20% risk. (ACOG)'),
    (v_topic_id, '240: "Gestational Trophoblastic Neoplasia" is diagnosed if hCG levels ____ over 3 weeks.', '["Decrease", "Plateau or increase", "Return to zero", "Drop by 50%"]', 1, 'Requires evaluation for choriocarcinoma. (Williams)'),
    (v_topic_id, '241: What is the first-line chemotherapy for "Low-Risk" Gestational Trophoblastic Neoplasia?', '["Cyclophosphamide", "Methotrexate or Actinomycin-D", "Cisplatin", "Doxorubicin"]', 1, 'Highly effective single-agent therapy. (ACOG)'),
    (v_topic_id, '242: A pregnant woman has "Mitral Stenosis." What happens to her symptoms during pregnancy?', '["They improve", "They often worsen (due to increased heart rate and cardiac output)", "No change", "She is cured"]', 1, 'High risk of heart failure/pulmonary edema. (Williams)'),
    (v_topic_id, '243: "Warfarin" exposure between 6-9 weeks gestation is associated with:', '["Fetal warfarin syndrome (nasal hypoplasia, stippled epiphyses)", "Heart defects", "Renal failure", "Blindness"]', 0, 'A classic teratogen; avoided if possible. (Gabbe)'),
    (v_topic_id, '244: A woman with "Epilepsy" is planning a pregnancy. What is the most important recommendation?', '["Stop all medications", "Achieve seizure control on a single medication (monotherapy) at the lowest effective dose", "Wait 10 years", "Only use valproic acid"]', 1, 'Polytherapy and valproic acid increase teratogenic risk. (ACOG)'),
    (v_topic_id, '245: "Valproic Acid" in pregnancy is specifically associated with which defect?', '["Cleft palate", "Neural tube defects (e.g., spina bifida)", "Heart defects", "Polydactyly"]', 1, 'Folic acid (4mg) should be taken. (ACOG)'),
    (v_topic_id, '246: A pregnant woman at 10 weeks has "Graves Disease" and is symptomatic. First-line treatment?', '["Methimazole", "Propylthiouracil (PTU)", "Atenolol", "Radioactive iodine"]', 1, 'PTU is used in the 1st trimester; switch to Methimazole in the 2nd. (ACOG)'),
    (v_topic_id, '247: "Propylthiouracil" (PTU) is avoided after the first trimester because of the risk of:', '["Fetal goiter", "Maternal hepatotoxicity", "Cleft palate", "None"]', 1, 'Methimazole is safer for the maternal liver. (ACOG)'),
    (v_topic_id, '248: A woman with "Asthma" is experiencing an exacerbation in pregnancy. Management?', '["Avoid all drugs", "Treat the same as a non-pregnant patient (SABA, steroids if needed)", "Only give oxygen", "Immediate delivery"]', 1, 'ACOG says "it is safer to treat the mother than to allow her to be hypoxic." (ACOG)'),
    (v_topic_id, '249: "Inhaled Corticosteroids" (e.g., Budesonide) are the preferred "controller" therapy for:', '["Hypertension", "Asthma", "Diabetes", "Nausea"]', 1, 'Budesonide is the most studied in pregnancy. (ACOG)'),
    (v_topic_id, '250: "Pruritic Urticarial Papules and Plaques of Pregnancy" (PUPPP) usually starts in which area?', '["The face", "Abdominal striae (stretch marks)", "The palms", "The scalp"]', 1, 'Often spreads to the limbs. (Beckmann)'),
    (v_topic_id, '251: Which TORCH infection is associated with "periventricular calcifications"?', '["Toxoplasmosis", "CMV", "Rubella", "Syphilis"]', 1, 'Toxo has diffuse calcifications. (Gabbe)'),
    (v_topic_id, '252: Maternal "Rubella" infection during the first 12 weeks of pregnancy results in fetal defects in up to ____ % of cases.', '["10%", "50%", "80-90%", "100%"]', 2, 'Congenital Rubella Syndrome is severe. (CDC)'),
    (v_topic_id, '253: A woman has "Hepatitis B" (HBsAg positive). What must the neonate receive at birth?', '["HBV vaccine", "HBV vaccine and Hepatitis B Immunoglobulin (HBIG)", "Antibiotics", "Nothing"]', 1, 'Reduces the risk of chronic infection significantly. (CDC)'),
    (v_topic_id, '254: "Vertical Transmission" of HIV occurs mostly:', '["In the 1st trimester", "During labor and delivery", "Postpartum through breastfeeding", "Both B and C"]', 3, 'Can be reduced to < 1% with modern care. (ACOG)'),
    (v_topic_id, '255: A "Prolonged latent phase" of labor (Stage 1) is defined as > ____ hours in a primigravida.', '["12", "20", "24", "48"]', 1, '20 hours for nulliparas; 14 hours for multiparas. (Williams)'),
    (v_topic_id, '256: "Arrest of Dilation" in the active phase is diagnosed after how many hours of adequate contractions with no change?', '["2", "4 (or 6 hours if contractions are inadequate)", "12", "24"]', 1, 'Current ACOG/SMFM criteria. (ACOG)'),
    (v_topic_id, '257: What is the primary risk of "Vacuum extraction"?', '["Maternal lacerations", "Fetal subgaleal hemorrhage (rare but life-threatening)", "Fetal heart defects", "Diabetes"]', 1, 'Requires close neonatal monitoring. (ACOG)'),
    (v_topic_id, '258: "Forceps" delivery is associated with a higher risk of which maternal injury compared to vacuum?', '["C-section", "3rd and 4th-degree perineal lacerations", "Nausea", "Bleeding"]', 1, 'Forceps are also more likely to cause fetal facial nerve palsy. (Williams)'),
    (v_topic_id, '259: "Amniotomy" (AROM) in a high, non-engaged head increases the risk of:', '["Infection", "Umbilical cord prolapse", "Bleeding", "Pain"]', 1, 'The head must be "well-applied" to the cervix. (Beckmann)'),
    (v_topic_id, '260: A woman has "Severe Pre-eclampsia" at 34 weeks. What is the most important medication to give before delivery?', '["Indomethacin", "Corticosteroids (Betamethasone) for lung maturity", "Oxytocin", "Heparin"]', 1, 'If status allows for a 24-48 hour delay. (ACOG)'),
    (v_topic_id, '261: "Magnesium Sulfate" toxicity can cause "cardiac arrest" at what serum level?', '["5 mg/dL", "10 mg/dL", "25-30 mg/dL", "100 mg/dL"]', 2, 'Respiratory arrest occurs around 12-15 mg/dL. (Williams)'),
    (v_topic_id, '262: A woman with GDM has "Polyhydramnios." What is the suspected mechanism?', '["Maternal thirst", "Fetal osmotic diuresis (high fetal glucose leads to high fetal urine)", "Infection", "Placental bleeding"]', 1, 'Similar to polyuria in adults with diabetes. (Gabbe)'),
    (v_topic_id, '263: "Shoulder Dystocia" is an emergency because of:', '["Maternal pain", "Fetal hypoxia due to umbilical cord compression in the birth canal", "Uterine rupture", "None"]', 1, 'Oxygen supply is compromised. (Williams)'),
    (v_topic_id, '264: "Erb-Duchenne Palsy" results in the arm being:', '["Flexed at the elbow", "Extended and internally rotated (Waiters tip position)", "Raised above the head", "None"]', 1, 'Due to C5-C6 stretch. (Beckmann)'),
    (v_topic_id, '265: A woman with "Prior uterine surgery" (e.g., myomectomy) presenting with new-onset abdominal pain should be evaluated for:', '["Appendicitis", "Uterine rupture/dehiscence", "Abruption", "Normal labor"]', 1, 'Always maintain a high index of suspicion for the scar. (ACOG)'),
    (v_topic_id, '266: "Amniotic Fluid Embolism" (AFE) can cause "Sinusoidal" FHR tracing due to:', '["Fetal sleep", "Acute fetal hypoxia from maternal collapse", "Maternal drugs", "Infection"]', 1, 'A late and ominous sign. (Gabbe)'),
    (v_topic_id, '267: "Postpartum Hemorrhage" (PPH) medications: "Misoprostol" (Cytotec) is often given:', '["IV", "Rectally or Sublingually", "In the skin", "By mask"]', 1, 'Common doses are 600-1000 mcg. (ACOG)'),
    (v_topic_id, '268: "Tranexamic Acid" (TXA) is used in PPH to:', '["Stop contractions", "Prevent fibrinolysis (breakdown of clots)", "Lower BP", "Treat infection"]', 1, 'The WOMAN trial showed it reduces mortality from PPH. (WHO/ACOG)'),
    (v_topic_id, '269: "Endometritis" is most commonly characterized by:', '["Lower abdominal pain, foul-smelling lochia, and uterine tenderness", "Breast pain", "Headache", "Cough"]', 0, 'Fever is the hallmark. (Beckmann)'),
    (v_topic_id, '270: "Septic Pelvic Thrombophlebitis" usually involves which vein?', '["Femoral", "Ovarian (usually the right)", "Saphenous", "Renal"]', 1, 'Reflects the drainage of the uterus. (Williams)'),
    (v_topic_id, '271: "Mastitis" is most commonly caused by:', '["Group B Strep", "Staphylococcus aureus", "E. coli", "Candida"]', 1, 'Usually from the infant''s nasopharynx. (ACOG)'),
    (v_topic_id, '272: A "Breast Abscess" requires:', '["Antibiotics only", "Drainage (needle or I&D) and antibiotics", "Stopping breastfeeding", "Mastectomy"]', 1, 'Failure to drain can lead to systemic illness. (Beckmann)'),
    (v_topic_id, '273: "Secondary Postpartum Hemorrhage" occurs:', '["In the 1st hour", "Between 24 hours and 12 weeks postpartum", "Before labor", "During labor"]', 1, 'Common causes include retained products or subinvolution. (Williams)'),
    (v_topic_id, '274: "Subinvolution of the placental site" presents with:', '["Immediate heavy bleeding", "Delayed, brisk bleeding around 1-2 weeks postpartum", "Fever", "Itching"]', 1, 'The spiral arteries fail to close properly. (Gabbe)'),
    (v_topic_id, '275: "Maternal Mortality" is defined as death during pregnancy or within ____ days of the end of pregnancy.', '["7", "42 (6 weeks)", "90", "365"]', 1, 'Standard WHO definition. (WHO)'),
    (v_topic_id, '276: A woman at 30 weeks has "Severe Pre-eclampsia." Her BP is 150/95 but her platelets are 80,000. Management?', '["Wait until 34 weeks", "Stabilization and delivery", "Steroids and wait 1 week", "Iron"]', 1, 'Low platelets (< 100k) is a severe feature; delivery is indicated. (ACOG)'),
    (v_topic_id, '277: "Magnesium Sulfate" in a patient with MG (Myasthenia Gravis) is:', '["Highly recommended", "Contraindicated", "Safe at high doses", "Used for pain"]', 1, 'Can cause respiratory failure. (Williams)'),
    (v_topic_id, '278: What is the "Kleihauer-Betke" result needed to give a standard 300 mcg dose of RhoGAM?', '["0.1%", "Any amount < 30 mL fetal blood", "10%", "50%"]', 1, 'One vial covers up to 30 mL of whole fetal blood. (ACOG)'),
    (v_topic_id, '279: "Vasa Previa" is associated with a fetal mortality rate of up to ____ % if undiagnosed prenatally.', '["5%", "25%", "60-90%", "100%"]', 2, 'Extremely high mortality due to rapid exsanguination. (Williams)'),
    (v_topic_id, '280: "Placenta Previa" in the mid-second trimester (20 weeks) is found in ~5% of women. How many will still have it at term?', '["1%", "< 10% (most migrate)", "50%", "100%"]', 1, 'Most "resolve" as the lower uterine segment develops. (ACOG)'),
    (v_topic_id, '281: "Active phase arrest" in labor is characterized by:', '["6 hours of oxytocin with no change", "4 hours of adequate contractions (> 200 MVUs) with no change", "Either A or B", "None"]', 2, 'Current SMFM/ACOG guidelines for C-section prevention. (ACOG)'),
    (v_topic_id, '282: "Vacuum" delivery is contraindicated if the gestational age is < ____ weeks.', '["32", "34", "37", "40"]', 1, 'Increases risk of intraventricular hemorrhage in preemies. (ACOG)'),
    (v_topic_id, '283: "Meconium Aspiration Syndrome" is prevented by:', '["Suctioning the head on the perineum", "Routine intubation of the infant", "Supportive care at birth (suctioning on the perineum is NOT recommended)", "Giving the mother antibiotics"]', 2, 'Current NRP guidelines advise against routine suctioning on the perineum. (AHA/AAP)'),
    (v_topic_id, '284: "Amnioinfusion" (putting fluid back into the uterus) is used during labor to:', '["Stop labor", "Reduce variable decelerations caused by cord compression", "Treat infection", "Measure weight"]', 1, 'Dilutes the meconium and cushions the cord. (ACOG)'),
    (v_topic_id, '285: "Chorioamnionitis" increase the risk of which neonatal complication?', '["Cerebral Palsy", "Neonatal sepsis", "Neonatal pneumonia", "All of the above"]', 3, 'Maternal infection is a significant risk for the neonate. (Williams)'),
    (v_topic_id, '286: A woman with "Sjögren syndrome" is at risk for which fetal complication?', '["Cleft palate", "Congenital heart block (due to anti-Ro/SSA antibodies)", "Limb defects", "Diabetes"]', 1, 'Requires fetal echos during pregnancy. (Gabbe)'),
    (v_topic_id, '287: "Postpartum Hemorrhage" - when should "Tranexamic Acid" be given?', '["Only after hysterectomy", "Within 3 hours of birth for any woman with PPH", "After 24 hours", "Only for C-sections"]', 1, 'Earlier administration is more effective. (WHO)'),
    (v_topic_id, '288: "Hegar sign" is found in the ____ trimester.', '["First", "Second", "Third", "Postpartum"]', 0, 'A sign of pregnancy. (Beckmann)'),
    (v_topic_id, '289: "Chadwick sign" involves the:', '["Uterus", "Cervix and Vagina (blue/purple color)", "Heart", "Skin"]', 1, 'A sign of pregnancy. (Williams)'),
    (v_topic_id, '290: "Normal Labor" Stage 2 is the time from:', '["Full dilation to delivery of the infant", "Contractions to full dilation", "Delivery of baby to delivery of placenta", "Placenta delivery to 1 hour"]', 0, 'Pushing phase. (Beckmann)'),
    (v_topic_id, '291: "Internal Podalic Version" is a maneuver used specifically for:', '["Breech twins", "Twin B (if malpresented) to allow vaginal delivery", "Singletons", "None"]', 1, 'Turning the second twin to a breech/footling presentation for extraction. (Williams)'),
    (v_topic_id, '292: "PPROM" at 35 weeks should be managed by:', '["Expectant management until 37 weeks", "Delivery", "Tocolytics for 1 week", "Steroids only and go home"]', 1, 'ACOG recommends delivery for PPROM at >= 34 weeks. (ACOG)'),
    (v_topic_id, '293: "Fetal Fibronectin" has its highest utility between:', '["12-20 weeks", "22-34 weeks", "37-40 weeks", "Postpartum"]', 1, 'Not reliable before 22 weeks or after 34 weeks. (ACOG)'),
    (v_topic_id, '294: "Indomethacin" for tocolysis is given for a maximum of ____ hours.', '["12", "48", "72", "1 week"]', 1, 'To minimize the risk of ductal closure and oligohydramnios. (ACOG)'),
    (v_topic_id, '295: "Betamethasone" dose for fetal lung maturity is:', '["6 mg every 12h x 4", "12 mg every 24h x 2", "12 mg once", "24 mg once"]', 1, 'Total dose of 24 mg. (ACOG)'),
    (v_topic_id, '296: "Dexamethasone" dose for fetal lung maturity is:', '["6 mg every 12h x 4", "12 mg every 24h x 2", "12 mg once", "None"]', 0, 'Total dose of 24 mg. (ACOG)'),
    (v_topic_id, '297: "Maternal Obesity" is a risk factor for "Fetal Macrosomia" even if the mother does NOT have:', '["Hypertension", "Diabetes", "Infection", "High age"]', 1, 'Obesity itself increases nutrient transfer to the fetus. (Williams)'),
    (v_topic_id, '298: "Post-term" pregnancy is defined as >= ____ weeks ____ days.', '["40; 0", "41; 0", "42; 0", "43; 0"]', 2, 'LMP-based definition. (ACOG)'),
    (v_topic_id, '299: "Late-term" pregnancy is defined as:', '["40 0/7 to 40 6/7", "41 0/7 to 41 6/7", "42 0/7 and beyond", "37 0/7 to 38 6/7"]', 1, 'A period of increasing risk before post-term. (ACOG)'),
    (v_topic_id, '300: "Early-term" pregnancy is defined as:', '["34 0/7 to 36 6/7", "37 0/7 to 38 6/7", "39 0/7 to 40 6/7", "None"]', 1, 'Associated with slightly higher risks than full-term (39+ weeks). (ACOG)');
